probes=[('ENC01','use sv_bis_i0205::FixedVector;','E0603'),('ENC02','use sv_bis_i0205::AdmittedDelivery;\npub fn forge(a:AdmittedDelivery)->AdmittedDelivery { AdmittedDelivery { ..a } }','E0451'),('ENC03','use sv_bis_i0205::AdmittedDelivery;\npub fn grow(a:&mut AdmittedDelivery) { a.vector().push(sv_core::Tri::U); }','E0599'),('ENC04','use sv_bis_i0205::AdmittedDelivery;\npub fn replace(a:&mut AdmittedDelivery) { a.vector()[0]=sv_core::Tri::U; }','E0594'),('ENC05','use sv_bis_i0205::AdmittedDelivery;\npub fn replace(a:&mut AdmittedDelivery) { a.descriptor()[0]=0; }','E0594'),('ENC06','use sv_bis_i0205::AdmittedDelivery;\npub fn replace(a:&mut AdmittedDelivery) { a.context().value=sv_bis_i0205::json::J::Null; }','E0616'),('ENC07','use sv_bis_i0205::AdmittedDelivery;\npub fn forge()->AdmittedDelivery { Default::default() }','E0277'),('ENC08','use sv_bis_i0205::AdmittedDelivery;\npub fn read(a:&AdmittedDelivery)->usize { a.vector().len()+a.descriptor().len() }',None)]
